query GetSaleOffGroup {
  sale_off_group(
    product_group_ud: "flashsale_samsung",

  ){
    group{
      product_group_ud
      product_group_name
      from_date
      to_date
      is_hotsale_by_time
      start_countdown_time
    }
    groupDetails{
      product_group_id
      product_id
      display_order
      sale_price_mien_bac
      sale_price_mien_nam
      additional_text
      gift
    }
  }
}
